// P12 로컬 골격: STORAGE-DESIGN 6.1 계약만 검사한다.
// 물리 저장소가 합의·연결되기 전에는 성공 StateRef를 만들거나 상태를 변경하지 않는다.
const input = $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v) => typeof v === 'string' && v.trim().length > 0;
const hasOwn = (v, key) => Object.prototype.hasOwnProperty.call(v, key);
const hasOnlyKeys = (v, allowed) => isObj(v) && Object.keys(v).every((key) => allowed.has(key));
const isNullableVersion = (v) => v === null || (Number.isInteger(v) && v >= 0);
const isStateRef = (v) => isObj(v) && isText(v.scope) && isText(v.request_id) && isText(v.owner_id) && isText(v.input_hash) && isText(v.execution_id) && Number.isInteger(v.state_revision) && v.state_revision >= 0;
const isSource = (v) => isObj(v) && isText(v.doc) && isText(v.section) && typeof v.score === 'number' && Number.isFinite(v.score);
const isFact = (v) => isObj(v) && isText(v.key) && typeof v.value === 'string' && ['user', 'document', 'api'].includes(v.origin) && (!hasOwn(v, 'reference') || typeof v.reference === 'string');
const isCaseFacts = (v) => isObj(v) && typeof v.summary === 'string' && Array.isArray(v.reported) && v.reported.every(isFact) && Array.isArray(v.confirmed) && v.confirmed.every(isFact) && Array.isArray(v.attempted_actions) && v.attempted_actions.every((item) => typeof item === 'string') && Array.isArray(v.missing) && v.missing.every((item) => typeof item === 'string') && Array.isArray(v.uncertainties) && v.uncertainties.every((item) => typeof item === 'string') && Array.isArray(v.evidence_refs) && v.evidence_refs.every(isSource);
const isOutcome = (v) => isObj(v) && ['guidance', 'ask', 'handoff', 'urgent', 'deny', 'failure'].includes(v.mode) && ['자동 답변', '보완 질문', '담당자 이관', '권한 없음', '차단'].includes(v.route) && typeof v.answer === 'string' && Array.isArray(v.sources) && v.sources.every(isSource) && typeof v.close_required === 'boolean' && isText(v.support_status) && (v.reason === null || typeof v.reason === 'string');
const isSecurity = (v) => isObj(v) && (v.blocked_by === null || typeof v.blocked_by === 'string') && (v.reason === null || typeof v.reason === 'string') && Number.isInteger(v.masked) && v.masked >= 0;
const isTicket = (v) => v === null || (isObj(v) && isText(v.ticket_id) && ['normal', 'high'].includes(v.priority) && typeof v.duplicate === 'boolean');
const isResponse = (v) => isObj(v) && isText(v.request_id) && ['자동 답변', '보완 질문', '담당자 이관', '권한 없음', '차단'].includes(v.route) && typeof v.answer === 'string' && Array.isArray(v.sources) && v.sources.every(isSource) && isTicket(v.ticket) && Array.isArray(v.agents) && v.agents.every(isText) && isSecurity(v.security);
const requestId = isObj(input) && isObj(input.state_ref) && isText(input.state_ref.request_id) ? input.state_ref.request_id : (isObj(input) && isObj(input.request) && isText(input.request.request_id) ? input.request.request_id : null);

if (!isObj(input) || !isText(input.op)) {
  return [{ json: { request_id: requestId, ok: false, skipped: false, state_ref: null, error_code: 'invalid_state_request' } }];
}

if (input.op === 'begin') {
  const valid = isText(input.scope) && isText(input.execution_id) && isText(input.input_hash) && isObj(input.actor) && isText(input.actor.id) && isObj(input.request) && isText(input.request.request_id);
  return [{ json: {
    request_id: requestId,
    mode: 'error',
    state_ref: null,
    support: null,
    facts: null,
    response: null,
    http_status: valid ? 503 : 400,
    error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request'
  } }];
}

if (input.op === 'save') {
  const valid = isStateRef(input.state_ref) && isText(input.case_id) && isText(input.first_request_id) && Number.isInteger(input.attempt) && input.attempt >= 1 && hasOwn(input, 'expected_case_version') && isNullableVersion(input.expected_case_version) && isText(input.ticket_id) && isCaseFacts(input.facts) && isOutcome(input.outcome) && isResponse(input.response);
  return [{ json: {
    request_id: requestId,
    ok: false,
    state_ref: null,
    error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request',
    recovery: { version: 1, mode: 'manual_required', action: 'finish', args: null, reference: null, reason: valid ? '물리 저장소 미연결' : '저장 요청 계약 오류' }
  } }];
}

const validatePrepare = (args) => hasOnlyKeys(args, new Set(['current_step'])) && isText(args.current_step);
const validateBind = (args) => {
  if (!hasOnlyKeys(args, new Set(['jira_issue_id', 'key', 'jira_issue_key', 'case_id', 'first_request_id', 'next_step']))) return false;
  const hasKey = hasOwn(args, 'key');
  const hasIssueKey = hasOwn(args, 'jira_issue_key');
  return isText(args.jira_issue_id) && hasKey !== hasIssueKey && isText(hasKey ? args.key : args.jira_issue_key) && isText(args.case_id) && isText(args.first_request_id) && isText(args.next_step);
};
const validateFinish = (args) => hasOnlyKeys(args, new Set(['response', 'current_step'])) && isResponse(args.response) && args.current_step === 'respond';
const validateFail = (args) => hasOnlyKeys(args, new Set(['status', 'current_step', 'error_code'])) && ['failed', 'unknown'].includes(args.status) && isText(args.current_step) && isText(args.error_code);
const validators = { prepare: validatePrepare, bind: validateBind, finish: validateFinish, fail: validateFail };
const validFailTarget = isStateRef(input.state_ref) || (input.state_ref === null && isText(input.scope) && isText(input.execution_id));
const validStateTarget = input.op === 'fail' ? validFailTarget : isStateRef(input.state_ref);
const valid = hasOwn(validators, input.op) && validStateTarget && isObj(input.args) && validators[input.op](input.args);
return [{ json: {
  request_id: requestId,
  ok: false,
  skipped: false,
  state_ref: null,
  error_code: valid ? 'state_backend_unconfigured' : 'invalid_state_request'
} }];
